sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float amount;
uniform float ridges;
uniform float style;
uniform float smoothness;
uniform float speed;
uniform float phase;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 d = coord - ctr;
    float r = length(d);
    float maxR = length(size) * 0.5;
    float2 dir = d / max(r, 0.001);
    float arg = r / maxR * ridges * 6.2831853 + radians(phase) + time * speed * 6.2831853;
    float tri = abs(fract(arg / 6.2831853) * 2.0 - 1.0) * 2.0 - 1.0;
    float w = mix(tri, sin(arg), smoothness);
    float2 disp = float2(-dir.y, dir.x) * w * amount;
    if (style > 0.5 && style < 1.5) disp = dir * w * amount;
    else if (style > 1.5) disp = dir * w * amount * exp(-r / (maxR * 0.5));
    return fin(c, tex(coord + disp), opacity);
}
